using System.Text.Json.Nodes;
using PowerShapeMcp;
internal static class CurveScaleStopRecoveryCheck {
 internal static int Preparation(string input,string output){var i=JsonNode.Parse(File.ReadAllText(input))!.AsObject();var p=CurveScaleStopRecoveryProof.Preparation(i["root"]!.GetValue<string>(),i["references"]!.AsObject());File.WriteAllText(output,new JsonObject{["state"]="passed",["nativeExpiry"]=p["expiresUtc"]!.DeepClone(),["originalExpiry"]=p["originalArguments"]!["expiresUtc"]!.DeepClone(),["sameAbsoluteTick"]=true,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine("PASS actual Native preparation bytes, equal absolute expiry; no CAD.");return 0;}
 internal static int Run(string input,string output){var rows=JsonNode.Parse(File.ReadAllText(input))!["rows"]!.AsArray();var row=rows.Single(r=>r!["fault"]!.GetValue<string>()=="control")!;string root=row["root"]!.GetValue<string>();var p=CurveScaleStopRecoveryProof.Preparation(root,row["references"]!.AsObject());var x=CurveScaleStopRecoveryProof.Execution(root,row["executionId"]!.GetValue<string>(),row["executionSha256"]!.GetValue<string>());var v=row["verificationResult"]!;var d=ArtifactProof.Verified(root,"curvescalestoprecoveryverifications",row["verificationId"]!.GetValue<string>(),v["diagnosticSha256"]!.GetValue<string>(),16000000);CurveScaleStopRecoveryProof.Diagnostic(root,d,x.Plan,p,row["verificationArguments"]!.AsObject());int cases=3;
  foreach(var fault in new[]{"point","magnitude","flag","solid","scale_success"}){var forged=d.DeepClone().AsObject();if(fault=="scale_success")forged["originalScaleSucceeded"]=true;else if(fault=="solid")forged["after"]!["entities"]![0]!["geometry"]!["cogRaw"]![0]=999;else{int field=fault=="point"?0:fault=="magnitude"?2:3;forged["captureObserved"]!["layout"]!["fields"]![field]!["values"]![0]=fault=="flag"?JsonValue.Create(true):JsonValue.Create(999);}bool rejected=false;try{CurveScaleStopRecoveryProof.Diagnostic(root,forged,x.Plan,p,row["verificationArguments"]!.AsObject());}catch(ReferenceRejected){rejected=true;}if(!rejected)throw new InvalidDataException("Forged recovery control proof accepted: "+fault);cases++;}
  var lost=rows.Single(r=>r!["fault"]!.GetValue<string>()=="throw_after")!;bool denied=false;try{_=CurveScaleStopRecoveryProof.Execution(lost["root"]!.GetValue<string>(),lost["executionId"]!.GetValue<string>(),lost["executionSha256"]!.GetValue<string>());}catch(ReferenceRejected){denied=true;}if(!denied)throw new InvalidDataException("Lost clear return accepted as authoritative");cases++;
  Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,new JsonObject{["state"]="passed",["cases"]=cases,["cadConnectionAttempted"]=false}.ToJsonString(new(){WriteIndented=true}));Console.WriteLine($"PASS: {cases} actual Framework/SDK recovery receipts/controls/lost-return refusal; no CAD.");return 0;
 }
}
